function predictDeliveryTime(input) {
    const numCols = MODEL_DATA.num_cols;
    const catCols = MODEL_DATA.cat_cols;
    const features = [];

    // 1. Standardize numerical inputs
    for (let i = 0; i < numCols.length; i++) {
        const col = numCols[i];
        const val = parseFloat(input[col]);
        const mean = MODEL_DATA.mean[i];
        const scale = MODEL_DATA.scale[i];
        features.push((val - mean) / scale);
    }

    // 2. One-hot encode categorical inputs
    for (let i = 0; i < catCols.length; i++) {
        const col = catCols[i];
        const selectedCat = input[col];
        const categories = MODEL_DATA.cat_categories[col];
        for (let j = 0; j < categories.length; j++) {
            features.push(selectedCat === categories[j] ? 1.0 : 0.0);
        }
    }

    // 3. Evaluate Gradient Boosting Decision Trees
    let prediction = MODEL_DATA.init_value;
    const lr = MODEL_DATA.learning_rate;
    const trees = MODEL_DATA.trees;

    for (let i = 0; i < trees.length; i++) {
        const tree = trees[i];
        let node = 0;
        while (tree.children_left[node] !== -1) {
            const featureIndex = tree.feature[node];
            const threshold = tree.threshold[node];
            if (features[featureIndex] <= threshold) {
                node = tree.children_left[node];
            } else {
                node = tree.children_right[node];
            }
        }
        prediction += lr * tree.value[node];
    }

    return Math.max(10, Math.round(prediction));
}
